findings.fix_text:
@media print{
  :root, :root[data-theme="dark"], :root:not([data-theme="light"]){--paper:#fff;--panel:#fff;--ink:#000;--muted:#333;--rule:#999;--accent:#000;--accent-ink:#000}
  .topbar nav, #lookup button{display:none}
  .band{color:#000;background:none!important;border:1.5px solid #000}
  .logo{color:#000;background:none;border:1px solid #000}
}

input[type=text]{flex:1 1 180px;min-width:0;padding:13px 14px;font:inherit;font-size:17px;border:1px solid var(--rule);border-radius:8px;background:var(--field);color:var(--ink)}
input[type=text]::placeholder{color:var(--muted);opacity:1}
#addr{flex-basis:240px}

